  `}function jO(t,e){const r=t.state,i=t.chunks[t.currentChunkIndex]||t.chunks[0],n=me.getCardsByDeck(t.id,!0),a=t.deckId?me.getCardsByDeck(t.deckId,!1):[],s=[...n,...a].filter((u,h,d)=>d.findIndex(f=>f.id===u.id)===h),o=i?s.filter(u=>u.chunkId===i.id):[],l=t.deckId?me.getDeckById(t.deckId):null,c=l?l.name:"Baraja sin vincular";return En===t.id?UO(t,i,o,c):`
